macro_rules! BitOps {
    () => {
        # [doc = " Bit counting and bit operations."] pub trait BitOps { # [doc = " Precision of this integer in bits."] fn bits_precision (& self) -> u32 ; # [doc = " `floor(log2(self.bits_precision()))`."] fn log2_bits (& self) -> u32 { u32 :: BITS - self . bits_precision () . leading_zeros () - 1 } # [doc = " Precision of this integer in bytes."] fn bytes_precision (& self) -> usize ; # [doc = " Get the value of the bit at position `index`, as a truthy or falsy `Choice`."] # [doc = " Returns the falsy value for indices out of range."] fn bit (& self , index : u32) -> Choice ; # [doc = " Sets the bit at `index` to 0 or 1 depending on the value of `bit_value`."] fn set_bit (& mut self , index : u32 , bit_value : Choice) ; # [doc = " Calculate the number of bits required to represent a given number."] fn bits (& self) -> u32 { self . bits_precision () - self . leading_zeros () } # [doc = " Calculate the number of trailing zeros in the binary representation of this number."] fn trailing_zeros (& self) -> u32 ; # [doc = " Calculate the number of trailing ones in the binary representation of this number."] fn trailing_ones (& self) -> u32 ; # [doc = " Calculate the number of leading zeros in the binary representation of this number."] fn leading_zeros (& self) -> u32 ; # [doc = " Returns `true` if the bit at position `index` is set, `false` otherwise."] # [doc = ""] # [doc = " # Remarks"] # [doc = " This operation is variable time with respect to `index` only."] fn bit_vartime (& self , index : u32) -> bool ; # [doc = " Calculate the number of bits required to represent a given number in variable-time with"] # [doc = " respect to `self`."] fn bits_vartime (& self) -> u32 ; # [doc = " Sets the bit at `index` to 0 or 1 depending on the value of `bit_value`,"] # [doc = " variable time in `self`."] fn set_bit_vartime (& mut self , index : u32 , bit_value : bool) ; # [doc = " Calculate the number of leading zeros in the binary representation of this number."] fn leading_zeros_vartime (& self) -> u32 { self . bits_precision () - self . bits_vartime () } # [doc = " Calculate the number of trailing zeros in the binary representation of this number in"] # [doc = " variable-time with respect to `self`."] fn trailing_zeros_vartime (& self) -> u32 ; # [doc = " Calculate the number of trailing ones in the binary representation of this number,"] # [doc = " variable time in `self`."] fn trailing_ones_vartime (& self) -> u32 ; }
    };
}

BitOps!()